'use strict';
// Differential harness: runs the original class-based implementation and the
// refactored one over the same scenarios and compares every observable effect.
// Usage: node diff-harness.js <oldDir> <newDir>
const path = require('node:path');

const [oldDir, newDir] = process.argv.slice(2).map(dir => path.resolve(dir));
if (!oldDir || !newDir) {
  console.error('usage: node diff-harness.js <oldDir> <newDir>');
  process.exit(2);
}
const impls = {
  old: require(path.join(oldDir, 'index.js')),
  new: require(path.join(newDir, 'index.js'))
};

const CHANNELS = ['email', 'sms', 'slack', 'inapp'];
const MINUTE = 60 * 1000;

function serialize(value) {
  return JSON.stringify(value, (key, v) => {
    if (v === undefined) return '<undefined>';
    if (v instanceof Map) return { '<Map>': [...v.entries()] };
    if (typeof v === 'function') return '<function>';
    return v;
  });
}

function describeError(error) {
  return {
    thrown: error && error.constructor ? error.constructor.name : typeof error,
    message: error && error.message
  };
}

function makeClock(startIso, stepMs) {
  const start = Date.parse(startIso);
  const clock = { calls: 0 };
  clock.now = () => new Date(start + clock.calls++ * stepMs);
  return clock;
}

function makeTransport(kind, trace) {
  if (kind === 'missing') return undefined;
  if (kind === 'null') return null;
  if (kind === 'empty') return {};
  if (kind === 'string-props') return { email: 'x', sms: 1, slack: null, inapp: {} };
  const transport = {};
  for (const name of CHANNELS) {
    if (kind === 'recording') {
      transport[name] = function (payload) {
        trace.push({ transport: name, args: arguments.length, bound: this === transport, payload });
        return 'ignored-return-value';
      };
    } else if (kind === 'async-recording') {
      transport[name] = async function (payload) {
        trace.push({ transport: name, args: arguments.length, bound: this === transport, payload });
      };
    } else if (kind === 'rejecting') {
      transport[name] = async () => {
        throw new Error(`${name} provider down`);
      };
    } else if (kind === 'sync-throwing') {
      transport[name] = () => {
        throw new RangeError(`${name} sync failure`);
      };
    } else if (kind === 'partial') {
      if (name === 'email' || name === 'slack') {
        transport[name] = payload => trace.push({ transport: name, payload });
      }
    } else {
      throw new Error(`unknown transport kind ${kind}`);
    }
  }
  return transport;
}

async function capture(fn) {
  let returned;
  try {
    returned = fn();
  } catch (error) {
    return { sync: true, ...describeError(error) };
  }
  if (returned && typeof returned.then === 'function') {
    try {
      return { promise: true, value: await returned };
    } catch (error) {
      return { promise: true, ...describeError(error) };
    }
  }
  return { value: returned };
}

async function runScenario(impl, scenario) {
  const trace = [];
  const clock = makeClock(scenario.clockStart || '2026-01-02T03:04:05.000Z', scenario.stepMs || 0);
  const store = scenario.noStore ? undefined : new Map((scenario.seed || []).map(([k, v]) => [k, [...v]]));
  const factoryOptions = { ...scenario.factoryOptions };
  if (!scenario.realClock) factoryOptions.now = clock.now;
  if (store) factoryOptions.throttleStore = store;
  const transport = makeTransport(scenario.transport || 'recording', trace);
  if (transport !== undefined) factoryOptions.transport = transport;

  let notifier;
  try {
    notifier = impl.createNotifier(scenario.channel, factoryOptions);
  } catch (error) {
    return serialize([{ createError: describeError(error) }]);
  }
  trace.push({ channel: notifier.channel });

  for (const step of scenario.steps) {
    const before = serialize([step.user, step.message, step.options, step.args]);
    const stage = step.stage || 'send';
    const args = step.args || [step.user, step.message, step.options];
    const outcome = await capture(() => notifier[stage](...args));
    trace.push({
      stage,
      outcome,
      inputsMutated: serialize([step.user, step.message, step.options, step.args]) !== before,
      store: store ? serialize(store) : null,
      clockCalls: clock.calls
    });
  }
  return serialize(trace);
}

// ---------------------------------------------------------------- scenarios
const invalidUsers = [null, undefined, 'u1', 42, () => {}, {}, { id: '' }, { id: 0 }, []];
const usersByChannel = {
  email: [
    { id: 'u1', name: 'Ava', email: 'ava@example.com', emailOptIn: true },
    { id: 'u 1/&?=', email: 'x@y', emailOptIn: false, locale: 'pt-BR' },
    { id: 7, name: '$& $1 $$', email: 'dollar@example.com' },
    { id: 'u2', email: 'no-at-sign' },
    { id: 'u3', email: 42 },
    { id: 'u4', email: ['@'] },
    { id: 'u5' },
    { id: 'u6', name: 'Zoë 🎉', email: 'zoe@example.com', emailOptIn: 1 }
  ],
  sms: [
    { id: 'u1', phone: '+15551234567', smsOptIn: true },
    { id: 'u2', phone: '+447911123456', smsOptIn: false, name: 'Bo' },
    { id: 'u3', phone: '555-1212' },
    { id: 'u4', phone: '+0123456789' },
    { id: 'u5', phone: '+1234567890123456' },
    { id: 'u6', phone: 15551234567 },
    { id: 'u7' },
    { id: 'u8', phone: '+1234567', smsOptIn: 'yes' }
  ],
  slack: [
    { id: 'u1', slackId: 'U1' },
    { id: 'u2', slackChannel: '#alerts', slackWorkspace: 'eng' },
    { id: 'u3', slackId: 'U3', slackChannel: '#c', name: 'Cy' },
    { id: 'u4' },
    { id: 'u5', slackId: '', slackChannel: '' }
  ],
  inapp: [
    { id: 'u1', name: 'Dee' },
    { id: 'u2', disabledInApp: true },
    { id: 'u3', disabledInApp: 0, locale: 'ja-JP' }
  ]
};

const messages = [
  null,
  'text',
  {},
  { title: 'T' },
  { body: 'B' },
  { title: '', body: 'B' },
  { title: 'Hello {{name}}', body: 'Your {{category}} update for {{id}} is ready {{name}}' },
  { title: 'Deal', body: 'Save now', category: 'marketing' },
  { title: 'Deal', body: 'Save now', category: 'marketing', priority: 'urgent' },
  { title: 'Login <b>"&\'', body: '<script>alert(1)</script>', category: 'security' },
  { title: 'Receipt', body: 'Paid', category: 'transactional', priority: 'normal' },
  { title: 'Deploy', body: 'Finished', category: 'release', priority: 'urgent', icon: 'rocket', actionUrl: '/deploys' },
  { title: 'A'.repeat(20), body: 'B'.repeat(300), priority: 'urgent', category: 'general' },
  { title: 123, body: 456, category: 'general' },
  { title: 'Café 🎉', body: '日本語のテキスト'.repeat(30), category: 'security', priority: 'urgent' },
  { title: '*bold*', body: 'x*y*z', category: 'release' }
];

const sendOptions = [
  undefined,
  {},
  null,
  { force: true },
  { locale: 'de-DE' },
  { channel: '#ops', threadTs: '171234.0001' },
  { threadTs: '1.2' },
  { actionUrl: '/security', expiresInHours: 1.37 },
  { expiresInHours: '2', channel: '' },
  { force: 1, actionUrl: '', expiresInHours: 1e12 }
];

const factorySets = [
  {},
  {
    from: 'alerts@example.com',
    replyTo: 'help@example.com',
    unsubscribeBaseUrl: 'https://u.example/x',
    senderId: 'ACME',
    segmentLength: 40,
    defaultWorkspace: 'product',
    defaultChannel: '#team',
    defaultIcon: 'star',
    defaultAction: '/inbox',
    defaultLocale: 'fr-FR',
    maxPerHour: 2
  },
  { maxPerHour: 0, segmentLength: 0, from: '', defaultLocale: '' },
  { maxPerHour: 'abc', segmentLength: 1 },
  { maxPerHour: 1, segmentLength: 5, channel: 'bogus', templates: { x: 1 }, defaultSender: 'Ops' }
];

function* matrixScenarios() {
  let index = 0;
  const steps = [0, 1, 7 * MINUTE];
  for (const channel of CHANNELS) {
    for (const factoryOptions of factorySets) {
      for (const user of [...invalidUsers, ...usersByChannel[channel]]) {
        for (const message of messages) {
          for (const options of sendOptions) {
            const send = { user, message, options };
            yield {
              name: `matrix#${index}`,
              channel,
              factoryOptions,
              stepMs: steps[index % steps.length],
              steps: [send, send, send]
            };
            index += 1;
          }
        }
      }
    }
  }
}

const validUser = {
  email: { id: 'u1', name: 'Ava', email: 'ava@example.com', emailOptIn: true },
  sms: { id: 'u1', phone: '+15551234567', smsOptIn: true },
  slack: { id: 'u1', slackId: 'U1', slackChannel: '#alerts' },
  inapp: { id: 'u1', name: 'Dee' }
};

function* throttleScenarios() {
  const categories = [undefined, 'general', 'marketing', 'security', 'release'];
  for (const channel of CHANNELS) {
    for (const maxPerHour of [1, 2, 3]) {
      for (const stepMs of [0, 7 * MINUTE, 20 * MINUTE, 59 * MINUTE, 61 * MINUTE]) {
        for (const seeded of [false, true]) {
          const steps = [];
          for (let i = 0; i < 12; i++) {
            const message = { title: `T${i}`, body: `B${i}`, category: categories[i % 3 === 2 ? 1 : 0] };
            if (i === 5) message.priority = 'urgent';
            if (i === 9) message.category = categories[(i + maxPerHour) % categories.length];
            const options = i === 7 ? { force: true } : i === 10 && channel === 'slack' ? { threadTs: '9.9' } : {};
            steps.push({ user: validUser[channel], message, options });
          }
          const seed = seeded
            ? [
                [`${channel}:u1:general`, [Date.parse('2026-01-02T02:30:00.000Z'), Date.parse('2026-01-02T01:00:00.000Z')]],
                [`${channel}:u1:security`, [Date.parse('2026-01-02T03:00:00.000Z')]]
              ]
            : [];
          yield { name: `throttle:${channel}:${maxPerHour}:${stepMs}:${seeded}`, channel, factoryOptions: { maxPerHour }, stepMs, seed, steps };
        }
      }
    }
  }
}

function* transportScenarios() {
  const kinds = ['recording', 'async-recording', 'missing', 'null', 'empty', 'string-props', 'rejecting', 'sync-throwing', 'partial'];
  for (const channel of CHANNELS) {
    for (const transport of kinds) {
      const send = { user: validUser[channel], message: { title: 'Hi {{name}}', body: 'Body', category: 'general' }, options: {} };
      yield { name: `transport:${channel}:${transport}`, channel, transport, factoryOptions: { maxPerHour: 2 }, stepMs: MINUTE, steps: [send, send, send] };
    }
  }
}

function* stageScenarios() {
  for (const channel of CHANNELS) {
    const user = validUser[channel];
    const message = { title: 'Hello {{name}}', body: 'Body {{id}}', category: 'marketing', priority: 'normal' };
    const steps = [
      { stage: 'validateUser', args: [user] },
      { stage: 'validateUser', args: [{ id: 'x' }] },
      { stage: 'validateUser', args: [null] },
      { stage: 'validateMessage', args: [message] },
      { stage: 'validateMessage', args: [{ title: 'only' }] },
      { stage: 'shouldThrottle', args: [user, message] },
      { stage: 'shouldThrottle', args: [user, message, { force: true }] },
      { stage: 'shouldThrottle', args: [{ ...user, emailOptIn: false, smsOptIn: false }, message] },
      { stage: 'format', args: [user, message] },
      { stage: 'format', args: [user, { ...message, category: 'security' }, { locale: 'es-MX', channel: '#x', threadTs: '1', actionUrl: '/a', expiresInHours: 3 }] },
      { stage: 'recordDelivery', args: [user, message] },
      { stage: 'recordDelivery', args: [user, { title: 'a', body: 'b' }] },
      { stage: 'shouldThrottle', args: [user, { title: 'a', body: 'b' }] },
      { stage: 'deliver', args: [{ id: 'payload-1' }] }
    ];
    yield { name: `stages:${channel}`, channel, factoryOptions: { maxPerHour: 1 }, stepMs: 13, steps };
  }
}

function* isolationScenarios() {
  // No throttleStore option: each notifier must get its own store.
  for (const channel of CHANNELS) {
    const send = { user: validUser[channel], message: { title: 'a', body: 'b' }, options: {} };
    yield { name: `own-store:${channel}`, channel, noStore: true, factoryOptions: { maxPerHour: 1 }, steps: [send, send] };
  }
}

// ------------------------------------------------------------------ runner
async function compareFactorySurface(mismatches) {
  const probes = {
    registryKeys: impl => Object.keys(impl.registry),
    registryTypes: impl => Object.values(impl.registry).map(value => typeof value),
    exportNames: impl => Object.keys(impl),
    allKeys: impl => Object.keys(impl.createAllNotifiers({})),
    allChannels: impl => Object.values(impl.createAllNotifiers()).map(n => n.channel),
    unknownFax: impl => impl.createNotifier('fax'),
    unknownUndefined: impl => impl.createNotifier(),
    unknownEmpty: impl => impl.createNotifier(''),
    unknownNumber: impl => impl.createNotifier(42),
    unknownCase: impl => impl.createNotifier('Email'),
    newRegistryEntry: impl => {
      const notifier = new impl.registry.email({ transport: { email() {} } });
      return [notifier.channel, typeof notifier.send];
    },
    noOptionsSendRejects: impl => impl.createNotifier('sms').send({ id: 'u', phone: '+15551234567' }, { title: 't', body: 'b' })
  };
  for (const [name, probe] of Object.entries(probes)) {
    const results = {};
    for (const [label, impl] of Object.entries(impls)) {
      results[label] = serialize(await capture(() => probe(impl)));
    }
    if (results.old !== results.new) mismatches.push({ name: `factory:${name}`, ...results });
  }

  // createAllNotifiers with one shared store: channels must not interfere.
  const sharedResults = {};
  for (const [label, impl] of Object.entries(impls)) {
    const store = new Map();
    const log = [];
    const clock = makeClock('2026-01-02T03:04:05.000Z', 1000);
    const all = impl.createAllNotifiers({ throttleStore: store, now: clock.now, maxPerHour: 1, transport: makeTransport('recording', log) });
    const out = [];
    for (const channel of CHANNELS) {
      out.push(await capture(() => all[channel].send(validUser[channel], { title: 'x', body: 'y' })));
      out.push(await capture(() => all[channel].send(validUser[channel], { title: 'x', body: 'y' })));
    }
    sharedResults[label] = serialize({ out, store, log, calls: clock.calls });
  }
  if (sharedResults.old !== sharedResults.new) mismatches.push({ name: 'factory:sharedStore', ...sharedResults });
}

async function main() {
  const mismatches = [];
  let count = 0;
  const groups = [matrixScenarios, throttleScenarios, transportScenarios, stageScenarios, isolationScenarios];
  for (const group of groups) {
    for (const scenario of group()) {
      count += 1;
      const oldTrace = await runScenario(impls.old, scenario);
      const newTrace = await runScenario(impls.new, scenario);
      if (oldTrace !== newTrace) mismatches.push({ name: scenario.name, old: oldTrace, new: newTrace });
    }
  }
  await compareFactorySurface(mismatches);

  console.log(`scenarios compared: ${count} (+ factory probes)`);
  console.log(`mismatches: ${mismatches.length}`);
  for (const mismatch of mismatches.slice(0, 5)) {
    console.log(`\n--- ${mismatch.name}`);
    console.log(`old: ${mismatch.old.slice(0, 1500)}`);
    console.log(`new: ${mismatch.new.slice(0, 1500)}`);
  }
  process.exitCode = mismatches.length === 0 ? 0 : 1;
}

main().catch(error => {
  console.error(error);
  process.exitCode = 2;
});

