function* throttleScenarios() {
  const categories = [undefined, 'general', 'marketing', 'security', 'release'];
  for (const channel of CHANNELS) {
    for (const maxPerHour of [1, 2, 3]) {
      for (const stepMs of [0, 7 * MINUTE, 20 * MINUTE, 59 * MINUTE, 61 * MINUTE]) {
        for (const seeded of [false, true]) {
          const steps = [];
