            const options = i === 7 ? { force: true } : i === 10 && channel === 'slack' ? { threadTs: '9.9' } : {};
            steps.push({ user: validUser[channel], message, options });
          }
          const seed = seeded
            ? [
                [`${channel}:u1:general`, [Date.parse('2026-01-02T02:30:00.000Z'), Date.parse('2026-01-02T01:00:00.000Z')]],
                [`${channel}:u1:security`, [Date.parse('2026-01-02T03:00:00.000Z')]]
              ]
            : [];
          yield { name: `throttle:${channel}:${maxPerHour}:${stepMs}:${seeded}`, channel, factoryOptions: { maxPerHour }, stepMs, seed, steps };
        }
      }
    }
  }
}

function* transportScenarios() {
  const kinds = ['recording', 'async-recording', 'missing', 'null', 'empty', 'string-props', 'rejecting', 'sync-throwing', 'partial'];
  for (const channel of CHANNELS) {
    for (const transport of kinds) {
      const send = { user: validUser[channel], message: { title: 'Hi {{name}}', body: 'Body', category: 'general' }, options: {} };
      yield { name: `transport:${channel}:${transport}`, channel, transport, factoryOptions: { maxPerHour: 2 }, stepMs: MINUTE, steps: [send, send, send] };
    }
  }
}

function* stageScenarios() {
  for (const channel of CHANNELS) {
    const user = validUser[channel];
    const message = { title: 'Hello {{name}}', body: 'Body {{id}}', category: 'marketing', priority: 'normal' };
    const steps = [
      { stage: 'validateUser', args: [user] },
      { stage: 'validateUser', args: [{ id: 'x' }] },
      { stage: 'validateUser', args: [null] },
      { stage: 'validateMessage', args: [message] },
      { stage: 'validateMessage', args: [{ title: 'only' }] },
      { stage: 'shouldThrottle', args: [user, message] },
      { stage: 'shouldThrottle', args: [user, message, { force: true }] },
      { stage: 'shouldThrottle', args: [{ ...user, emailOptIn: false, smsOptIn: false }, message] },
      { stage: 'format', args: [user, message] },
      { stage: 'format', args: [user, { ...message, category: 'security' }, { locale: 'es-MX', channel: '#x', threadTs: '1', actionUrl: '/a', expiresInHours: 3 }] },
      { stage: 'recordDelivery', args: [user, message] },
      { stage: 'recordDelivery', args: [user, { title: 'a', body: 'b' }] },
      { stage: 'shouldThrottle', args: [user, { title: 'a', body: 'b' }] },
      { stage: 'deliver', args: [{ id: 'payload-1' }] }
    ];
    yield { name: `stages:${channel}`, channel, factoryOptions: { maxPerHour: 1 }, stepMs: 13, steps };
  }
}

function* isolationScenarios() {
  // No throttleStore option: each notifier must get its own store.
  for (const channel of CHANNELS) {
    const send = { user: validUser[channel], message: { title: 'a', body: 'b' }, options: {} };
    yield { name: `own-store:${channel}`, channel, noStore: true, factoryOptions: { maxPerHour: 1 }, steps: [send, send] };
  }
}

// ------------------------------------------------------------------ runner
async function compareFactorySurface(mismatches) {
  const probes = {
    registryKeys: impl => Object.keys(impl.registry),
    registryTypes: impl => Object.values(impl.registry).map(value => typeof value),
    exportNames: impl => Object.keys(impl),
    allKeys: impl => Object.keys(impl.createAllNotifiers({})),
    allChannels: impl => Object.values(impl.createAllNotifiers()).map(n => n.channel),
    unknownFax: impl => impl.createNotifier('fax'),
    unknownUndefined: impl => impl.createNotifier(),
    unknownEmpty: impl => impl.createNotifier(''),
    unknownNumber: impl => impl.createNotifier(42),
    unknownCase: impl => impl.createNotifier('Email'),
    newRegistryEntry: impl => {
      const notifier = new impl.registry.email({ transport: { email() {} } });
      return [notifier.channel, typeof notifier.send];
    },
    noOptionsSendRejects: impl => impl.createNotifier('sms').send({ id: 'u', phone: '+15551234567' }, { title: 't', body: 'b' })
  };
  for (const [name, probe] of Object.entries(probes)) {
    const results = {};
    for (const [label, impl] of Object.entries(impls)) {
      results[label] = serialize(await capture(() => probe(impl)));
    }
    if (results.old !== results.new) mismatches.push({ name: `factory:${name}`, ...results });
  }

  // createAllNotifiers with one shared store: channels must not interfere.
  const sharedResults = {};
  for (const [label, impl] of Object.entries(impls)) {
    const store = new Map();
    const log = [];
    const clock = makeClock('2026-01-02T03:04:05.000Z', 1000);
    const all = impl.createAllNotifiers({ throttleStore: store, now: clock.now, maxPerHour: 1, transport: makeTransport('recording', log) });
    const out = [];
    for (const channel of CHANNELS) {
      out.push(await capture(() => all[channel].send(validUser[channel], { title: 'x', body: 'y' })));
      out.push(await capture(() => all[channel].send(validUser[channel], { title: 'x', body: 'y' })));
    }
    sharedResults[label] = serialize({ out, store, log, calls: clock.calls });
  }
  if (sharedResults.old !== sharedResults.new) mismatches.push({ name: 'factory:sharedStore', ...sharedResults });
}

async function main() {
  const mismatches = [];
  let count = 0;
  const groups = [matrixScenarios, throttleScenarios, transportScenarios, stageScenarios, isolationScenarios];
  for (const group of groups) {
    for (const scenario of group()) {
      count += 1;
      const oldTrace = await runScenario(impls.old, scenario);
      const newTrace = await runScenario(impls.new, scenario);
      if (oldTrace !== newTrace) mismatches.push({ name: scenario.name, old: oldTrace, new: newTrace });
    }
  }
  await compareFactorySurface(mismatches);

  console.log(`scenarios compared: ${count} (+ factory probes)`);
  console.log(`mismatches: ${mismatches.length}`);
  for (const mismatch of mismatches.slice(0, 5)) {
    console.log(`\n--- ${mismatch.name}`);
    console.log(`old: ${mismatch.old.slice(0, 1500)}`);
    console.log(`new: ${mismatch.new.slice(0, 1500)}`);
  }
  process.exitCode = mismatches.length === 0 ? 0 : 1;
}

main().catch(error => {
  console.error(error);
  process.exitCode = 2;
});

