/** Maximum length of the shared `preview`; Slack reuses it for its own preview. */
const PREVIEW_LENGTH = 120;

/** Fills the {{name}}, {{id}} and {{category}} placeholders in a message field. */
function applyTemplate(value, user, message) {
  return String(value)
    .replace(/\{\{name\}\}/g, user.name || 'there')
    .replace(/\{\{id\}\}/g, user.id)
    .replace(/\{\{category\}\}/g, message.category || 'general');
}

/**
 * Builds the channel-independent payload fields. The clock is read twice, for
 * `id` and then `generatedAt`, so a stepping clock gives them different times.
 */
function formatBase({ channel, user, message, options, defaultLocale, now }) {
  const id = `${channel}-${user.id}-${now().getTime()}`;
  const locale = options.locale || user.locale || defaultLocale;
  const title = applyTemplate(message.title, user, message);
  const body = applyTemplate(message.body, user, message);

  return {
    id,
    channel,
    locale,
    title,
    body,
    preview: `${title}: ${body}`.slice(0, PREVIEW_LENGTH),
    metadata: {
      category: message.category || 'general',
      priority: message.priority || 'normal',
      generatedAt: now().toISOString()
    }
  };
}

module.exports = {
  PREVIEW_LENGTH,
  applyTemplate,
  formatBase
};

