  fs.writeFileSync(target, mutated);

  let caught;
  try {
    execFileSync(process.execPath, [path.join(scratch, 'diff-harness.js'), oldDir, mutantDir], { stdio: 'pipe' });
    caught = false;
  } catch (error) {
    caught = error.status === 1;
    if (error.status !== 1) console.log(error.stderr.toString());
  }
  if (!caught) survived += 1;
  console.log(`${caught ? 'caught  ' : 'SURVIVED'} ${file}: ${from.split('\n')[0].slice(0, 70)}`);
}
fs.rmSync(path.join(scratch, 'mutant'), { recursive: true, force: true });
console.log(`\n${mutations.length - survived}/${mutations.length} mutations caught`);
process.exitCode = survived === 0 ? 0 : 1;

